mapper.select:
SELECT fm.file_path AS filePath , ib.board_no AS boardNo , ib.title AS title , u.user_name AS regUser , DATE_FORMAT(ib.reg_date, '%Y-%m-%d') AS regDate , ib.hit AS hit FROM image_board ib JOIN file_master fm ON ib.thumb_file_no = fm.file_no JOIN users u ON ib.reg_user = u.user_no
AND ( ib.title LIKE CONCAT('%', #{searchKeyword}, '%') OR u.user_name LIKE CONCAT('%', #{searchKeyword}, '%') )
ORDER BY ib.board_no DESC LIMIT #{firstIndex}, #{recordCountPerPage}

mapper.insert:
INSERT INTO image_board
(
board_no						
, title							
, content						
, file_group_id			
, thumb_file_no			
, hit								
, use_yn						
, reg_date					
, reg_user					
, mod_date					
, mod_user					
)
VALUES
(
, #{boardNo}
, #{title}
, #{content}
, #{fileGroupId}
, #{thumbFileNo}
, #{hit}
, 'Y'
, NOW()
, #{regUser}
, NULL
, NULL
);
